import { PathlandNode } from '../../core/retained-tree';
import { PathlandNodeHost } from './node-host';
import { NotImplementedComponent } from '../not-implemented.component';
import { pickerStyle, selection, selectionString } from '../mapping';

/** Lazy `PICKER` node: select (menu) / segmented / radio group per `PICKER_STYLE`. */
@Component({
  selector: 'pathland-picker-node',
  imports: [HStack, Button, RadioGroup, Option, Select, NotImplementedComponent],
  template: `
    @let n = node();
    @if (n; as node) {
      @if (pickerStyle(node) === 'segmented') {
        <ui-hstack [gap]="4">
          @for (opt of options(node); track opt.index) {
            <ui-button
              [label]="selection(node) === opt.index ? opt.label + ' ✓' : opt.label"
              (click)="onIndex(nodeId(), opt.index)">
            </ui-button>
          }
        </ui-hstack>
      } @else if (pickerStyle(node) === 'radioGroup') {
        <ui-radio-group
          label=""
          [value]="selectionString(node)"
          (valueChange)="onSelect(nodeId(), $event)">
          @for (opt of options(node); track opt.index) {
            <div [option]="'' + opt.index">{{ opt.label }}</div>
          }
        </ui-radio-group>
      } @else if (pickerStyle(node) === 'wheel') {
        <pathland-not-implemented name="PICKER::Wheel" />
      } @else {
        <ui-select
          [value]="selectionString(node)"
          (valueChange)="onSelect(nodeId(), $event)">
          @for (opt of options(node); track opt.index) {
            <div [option]="'' + opt.index">{{ opt.label }}</div>
          }
        </ui-select>
      }
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PickerNodeComponent extends PathlandNodeHost {
  pickerStyle = pickerStyle;
  selection = selection;
  selectionString = selectionString;

  onIndex(nodeId: number, index: number): void {
    this.session.sendValueChanged(nodeId, index);
  }

  onSelect(nodeId: number, value: string | undefined): void {
    if (value === undefined) {
      return;
    }
    this.session.sendValueChanged(nodeId, Number(value));
  }

  /** The picker's options: child node texts with their display order index. */
  options(n: PathlandNode): { index: number; label: string }[] {
    return n.children()
      .map((id) => this.session.tree.node(id))
      .filter((c): c is PathlandNode => c !== undefined)
      .map((c, index) => ({ index, label: c.text() ?? '' }));
  }
}

import { ChangeDetectionStrategy, Component } from '@angular/core';
import { HStack } from '@apaq/ngui-elements/core';
import { Button, Menu, Option } from '@apaq/ngui-elements/components';
import { TriggerFor } from '@apaq/ngui-elements/overlay';
import { PathlandNode } from '../../core/retained-tree';
import { PathlandNodeHost } from './node-host';

/** Lazy `MENU` node: trigger button + popup menu; selection reports `VALUE_CHANGED`. */
@Component({
  selector: 'pathland-menu-node',
  imports: [HStack, Button, Menu, Option, TriggerFor],
  template: `
    @let n = node();
    @if (n; as node) {
      <ui-hstack [gap]="0">
        <ui-button [triggerFor]="menu" [label]="triggerLabel(node)"></ui-button>
        <ui-menu #menu (onSelect)="onSelect(nodeId(), $event)">
          @for (opt of items(node); track opt.index) {
            <div [option]="'' + opt.index">{{ opt.label }}</div>
          }
        </ui-menu>
      </ui-hstack>
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MenuNodeComponent extends PathlandNodeHost {
  onSelect(nodeId: number, value: string | undefined): void {
    if (value === undefined) {
      return;
    }
    this.session.sendValueChanged(nodeId, Number(value));
  }

  /** The menu's action items: children after the trigger, indexed from 0. */
  items(n: PathlandNode): { index: number; label: string }[] {
    return n.children()
      .slice(1)
      .map((id) => this.session.tree.node(id))
      .filter((c): c is PathlandNode => c !== undefined)
      .map((c, index) => ({ index, label: c.text() ?? '' }));
  }

  /** The menu's trigger label: the first child's text. */
  triggerLabel(n: PathlandNode): string {
    const trigger = n.children().length > 0 ? this.session.tree.node(n.children()[0]) : undefined;
    return trigger?.text() ?? 'Menu';
  }
}

import { ChangeDetectionStrategy, Component } from '@angular/core';
import { DatePicker } from '@apaq/ngui-elements/date-picker';
import { PathlandNodeHost } from './node-host';
import { NotImplementedComponent } from '../not-implemented.component';
import { datePickerMode, dateValue } from '../mapping';

/** Lazy `DATE_PICKER` node (DATE mode); Time/DateAndTime modes are placeholders. */
@Component({
  selector: 'pathland-date-picker-node',
  imports: [DatePicker, NotImplementedComponent],
  template: `
    @let n = node();
    @if (n; as node) {
      @if (datePickerMode(node) === 'date') {
        <ui-date-picker
          [value]="dateValue(node)"
          (valueChange)="onDate(nodeId(), $event)">
        </ui-date-picker>
      } @else if (datePickerMode(node) === 'time') {
        <pathland-not-implemented name="DATE_PICKER::Time" />
      } @else {
        <pathland-not-implemented name="DATE_PICKER::DateAndTime" />
      }
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DatePickerNodeComponent extends PathlandNodeHost {
  datePickerMode = datePickerMode;
  dateValue = dateValue;

  onDate(nodeId: number, value: string | undefined): void {
    if (!value) {
      return;
    }
    const [y, m, d] = value.split('-').map(Number);
    const days = Math.round(Date.UTC(y, m - 1, d) / 86_400_000);
    this.session.sendDateChanged(nodeId, days, 0);
  }
}

import { ChangeDetectionStrategy, Component, inject, input } from '@angular/core';
import {
  HStack, VStack, ZStack, Text, Image, ScrollView, SpacerComponent, Grid, Rectangle, Circle,
  Padding, Color, Background, Border, Rounding, Opacity, Font, Flex, Frame, LineLimit, ForegroundStyle,
  Shadow, RotationEffect, Underline,
} from '@apaq/ngui-elements/core';
import { COMPONENT, SHAPE_KIND } from '../core/protocol';
import { PathlandNode } from '../core/retained-tree';
import { PathlandSession } from './session.service';
import { NotImplementedComponent } from './not-implemented.component';
import { ButtonNodeComponent } from './nodes/button-node.component';
import { ToggleNodeComponent } from './nodes/toggle-node.component';
import { TextFieldNodeComponent } from './nodes/text-field-node.component';
import { TextEditorNodeComponent } from './nodes/text-editor-node.component';
import { PickerNodeComponent } from './nodes/picker-node.component';
import { MenuNodeComponent } from './nodes/menu-node.component';
import { DatePickerNodeComponent } from './nodes/date-picker-node.component';
import {
  buildMods, colorFill, hidden, imageSource, kindOf, shapeKind, stackAlignment, stackGap,
  textAlignment, zstackAlignment,
} from './mapping';

/**
 * The recursive ngui renderer driver. The `@apaq/ngui` **core** views (stacks,
 * grids, text, image, spacer, shapes, scroll view) are always needed and stay
 * eager; every **control** kind (button, toggle, text field/editor, picker,
 * menu, date picker) is rendered by a per-kind lazy node loaded via
 * `@defer (on immediate)` so its ngui entry point is only fetched when that
 * kind actually appears in the tree. Protocol components with no ngui
 * equivalent render a "not implemented" placeholder.
 */
@Component({
  selector: 'pathland-node',
  imports: [
    HStack, VStack, ZStack, Text, Image, ScrollView, SpacerComponent, Grid, Rectangle, Circle,
    Padding, Color, Background, Border, Rounding, Opacity, Font, Flex, Frame, LineLimit,
    ForegroundStyle, Shadow, RotationEffect, Underline,
    NotImplementedComponent,
    ButtonNodeComponent, ToggleNodeComponent, TextFieldNodeComponent, TextEditorNodeComponent,
    PickerNodeComponent, MenuNodeComponent, DatePickerNodeComponent,
  ],
  templateUrl: './node.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PathlandNodeComponent {
  readonly nodeId = input.required<number>();
  readonly session = inject(PathlandSession);

  readonly SHAPE_KIND = SHAPE_KIND;

  nodeOf = (id: number): PathlandNode | undefined => this.session.tree.node(id);
  kindOf = kindOf;
  mods = buildMods;
  stackGap = stackGap;
  stackAlignment = stackAlignment;
  zstackAlignment = zstackAlignment;
  textAlignment = textAlignment;
  hidden = hidden;
  colorFill = colorFill;
  shapeKind = shapeKind;
  imageSource = imageSource;

  /** Whether the node must be ignored: `COMMENT` (opaque/debug, no native element). */
  ignored = (n: PathlandNode): boolean => n.component === COMPONENT.COMMENT;
}

import { computed, Directive, inject, input } from '@angular/core';
import { PathlandNode } from '../../core/retained-tree';
import { PathlandSession } from '../session.service';

/**
 * Shared host for the lazy per-kind node components: resolves the retained node
 * from the session tree by {@link nodeId}. Each subclass is a standalone
 * component loaded via `@defer (on immediate)` so its `@apaq/ngui` entry point
 * is only fetched when that kind actually appears in the tree.
 */
@Directive()
export abstract class PathlandNodeHost {
  readonly nodeId = input.required<number>();
  readonly session = inject(PathlandSession);
  readonly node = computed<PathlandNode | undefined>(() => this.session.tree.node(this.nodeId()));
}

