fn apply_text(class: &str, s: &mut EmbeddedStyle, ctx: Ctx<'_>) {
 if let Some(rest) = class.strip_prefix("text-") {
 if let Some(c) = resolve_color_token(rest, ctx) {
 s.text = Some(c);
