// The Pathland DOM renderer bootstrap. Hydrates the server-rendered DOM,
// connects to the WebSocket, applies PLPL deltas in place, and reports raw
// inputs back as host → guest EVENT batches (gated by EVENT_LISTENERS when the
// SSR HTML carries a `data-event-listeners` mask). Bundle: dist/pathland-dom-renderer.js

import type { DomRenderer } from "./apply";
import { Transport } from "./transport";
import {
  encodeDateChanged,
  encodeEditingChanged,
  encodeFocusChanged,
  encodeKeyDown,
  encodeKeyUp,
  encodePointerDown,
  encodePointerMove,
  encodePointerUp,
  encodeScroll,
  encodeTextChanged,
  encodeValueBits,
  encodeValueChanged,
  encodeWheel,
} from "./events";
import {
  FLAG_HOVER_ENTER,
  FLAG_HOVER_LEAVE,
  FLAG_POINTER_SECONDARY,
  LISTEN_EDITING,
  LISTEN_FOCUS,
  LISTEN_KEY_DOWN,
  LISTEN_KEY_UP,
  LISTEN_POINTER_DOWN,
  LISTEN_POINTER_MOVE,
  LISTEN_POINTER_UP,
  LISTEN_SCROLL,
  LISTEN_WHEEL,
} from "./constants";

/** The owning Pathland node (the closest `[data-pathland-id]` ancestor). */
function nodeOf(el: Element | null): HTMLElement | null {
  return el ? el.closest<HTMLElement>("[data-pathland-id]") : null;
}

/**
 * EVENT_LISTENERS gating: emit an event only if the node's `data-event-listeners`
 * mask (from the SSR HTML, mirroring the Rust renderer's event attrs) requests it.
 * When the attribute is absent there is no gating information — be permissive.
 */
function listens(node: HTMLElement | null, bit: number): boolean {
  if (!node) {
    return false;
  }
  const raw = node.getAttribute("data-event-listeners");
  if (raw === null) {
    return true;
  }
  return (Number(raw) & bit) !== 0;
}

function modifiersOf(e: KeyboardEvent): number {
  let m = 0;
  if (e.shiftKey) m |= 0x01;
  if (e.ctrlKey) m |= 0x02;
  if (e.altKey) m |= 0x04;
  if (e.metaKey) m |= 0x08;
  return m;
}

function keyCodeOf(e: KeyboardEvent): number {
  return typeof e.keyCode === "number" && e.keyCode !== 0 ? e.keyCode : e.key.charCodeAt(0);
}

function boot(): void {
  const byId = new Map<number, Node>();
  for (const el of document.querySelectorAll<HTMLElement>("[data-pathland-id]")) {
    byId.set(Number(el.getAttribute("data-pathland-id")), el);
  }
  const renderer: DomRenderer = { byId };
  const transport = new Transport({
    url: `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/ws`,
    renderer,
  });
  transport.start();

  // Hover tracking for POINTER_MOVE enter/leave.
  const hovered = new WeakSet<Element>();

  // --- pointer: down / move (hover) / up (tap) ---
  document.addEventListener("pointerdown", (event) => {
    const node = nodeOf(event.target as Element);
    if (!transport.open || !listens(node, LISTEN_POINTER_DOWN)) {
      return;
    }
    const id = Number(node!.getAttribute("data-pathland-id"));
    const secondary = event.button !== 0 ? FLAG_POINTER_SECONDARY : 0;
    transport.send(encodePointerDown(id, event.clientX, event.clientY, secondary));
  });

  document.addEventListener("pointermove", (event) => {
    const target = event.target as Element;
    const node = nodeOf(target);
    if (!transport.open || !listens(node, LISTEN_POINTER_MOVE)) {
      return;
    }
    const id = Number(node!.getAttribute("data-pathland-id"));
    if (!hovered.has(target)) {
      hovered.add(target);
      transport.send(encodePointerMove(id, event.clientX, event.clientY, FLAG_HOVER_ENTER));
    }
  });
  document.addEventListener("pointerout", (event) => {
    const target = event.target as Element;
    const node = nodeOf(target);
    if (hovered.has(target)) {
      hovered.delete(target);
      if (transport.open && listens(node, LISTEN_POINTER_MOVE)) {
        const id = Number(node!.getAttribute("data-pathland-id"));
        transport.send(encodePointerMove(id, event.clientX, event.clientY, FLAG_HOVER_LEAVE));
      }
    }
  });

  document.addEventListener("click", (event) => {
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const button = nodeOf(target);
    if (button && button.matches("button") && transport.open && listens(button, LISTEN_POINTER_UP)) {
      const id = Number(button.getAttribute("data-pathland-id"));
      const secondary = (event as MouseEvent).button !== 0 ? FLAG_POINTER_SECONDARY : 0;
      transport.send(encodePointerUp(id, (event as MouseEvent).clientX, (event as MouseEvent).clientY, secondary));
      return;
    }
    const stepButton = target.closest<HTMLElement>(".pathland-stepper button[data-step]");
    if (stepButton && transport.open) {
      const stepper = stepButton.closest<HTMLElement>(".pathland-stepper[data-pathland-id]");
      if (stepper) {
        const id = Number(stepper.getAttribute("data-pathland-id"));
        const valueEl = stepper.querySelector("span");
        const rangeEl = stepper.querySelector<HTMLElement>(".pathland-stepper-range");
        const current = Number(valueEl ? valueEl.textContent : 0);
        const dir = Number(stepButton.getAttribute("data-step"));
        const min = Number(rangeEl?.getAttribute("data-min"));
        const max = Number(rangeEl?.getAttribute("data-max"));
        const step = Number(rangeEl?.getAttribute("data-step"));
        const next = Math.min(max, Math.max(min, current + dir * step));
        transport.send(encodeValueChanged(id, next));
      }
    }
  });

  // --- keyboard (reported to the focused node) ---
  document.addEventListener("keydown", (event) => {
    const node = nodeOf(document.activeElement);
    if (!transport.open || !listens(node, LISTEN_KEY_DOWN)) {
      return;
    }
    transport.send(
      encodeKeyDown(Number(node!.getAttribute("data-pathland-id")), keyCodeOf(event), modifiersOf(event), event.repeat),
    );
  });
  document.addEventListener("keyup", (event) => {
    const node = nodeOf(document.activeElement);
    if (!transport.open || !listens(node, LISTEN_KEY_UP)) {
      return;
    }
    transport.send(
      encodeKeyUp(Number(node!.getAttribute("data-pathland-id")), keyCodeOf(event), modifiersOf(event)),
    );
  });

  // --- focus / editing (text inputs + editors) ---
  function focusTarget(event: FocusEvent): HTMLElement | null {
    const input = event.target as Element | null;
    if (!input || (!input.matches("input[type=text],input[type=password],textarea"))) {
      return null;
    }
    return nodeOf(input);
  }
  document.addEventListener("focusin", (event) => {
    const node = focusTarget(event);
    if (!transport.open || !node) {
      return;
    }
    const id = Number(node.getAttribute("data-pathland-id"));
    if (listens(node, LISTEN_FOCUS)) {
      transport.send(encodeFocusChanged(id, true));
    }
    if (listens(node, LISTEN_EDITING)) {
      transport.send(encodeEditingChanged(id, true));
    }
  });
  document.addEventListener("focusout", (event) => {
    const node = focusTarget(event);
    if (!transport.open || !node) {
      return;
    }
    const id = Number(node.getAttribute("data-pathland-id"));
    if (listens(node, LISTEN_FOCUS)) {
      transport.send(encodeFocusChanged(id, false));
    }
    if (listens(node, LISTEN_EDITING)) {
      transport.send(encodeEditingChanged(id, false));
    }
  });

  // --- scroll / wheel (scroll containers) ---
  document.addEventListener("scroll", (event) => {
    const scroller = event.target as Element | null;
    const node = nodeOf(scroller);
    if (!transport.open || !listens(node, LISTEN_SCROLL)) {
      return;
    }
    const el = scroller instanceof Element ? scroller : document.documentElement;
    transport.send(
      encodeScroll(Number(node!.getAttribute("data-pathland-id")), el.scrollLeft, el.scrollTop),
    );
  }, true);
  document.addEventListener(
    "wheel",
    (event) => {
      const node = nodeOf(event.target as Element);
      if (!transport.open || !listens(node, LISTEN_WHEEL)) {
        return;
      }
      transport.send(encodeWheel(Number(node!.getAttribute("data-pathland-id")), event.deltaX, event.deltaY));
    },
    { passive: true },
  );

  // --- value-bearing controls (toggles/selects/color/date) ---
  document.addEventListener("change", (event) => {
    if (!transport.open) {
      return;
    }
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const toggle = target.closest<HTMLElement>("label.pathland-toggle[data-pathland-id]");
    if (toggle) {
      const box = toggle.querySelector<HTMLInputElement>("input[type=checkbox]");
      transport.send(
        encodeValueChanged(Number(toggle.getAttribute("data-pathland-id")), box && box.checked ? 1 : 0),
      );
      return;
    }
    const select = target.closest<HTMLSelectElement>("select[data-pathland-id]");
    if (select) {
      transport.send(encodeValueChanged(Number(select.getAttribute("data-pathland-id")), Number(select.value)));
      return;
    }
    const color = target.closest<HTMLInputElement>("input[type=color][data-pathland-id]");
    if (color) {
      const rgb = parseInt(color.value.slice(1), 16);
      transport.send(encodeValueBits(Number(color.getAttribute("data-pathland-id")), 0xff000000 | rgb));
      return;
    }
    const date = target.closest<HTMLInputElement>("input[type=date],input[type=time],input[type=datetime-local][data-pathland-id]");
    if (date) {
      const id = Number(date.getAttribute("data-pathland-id"));
      if (date.value) {
        if (date.type === "time") {
          const [h, m] = date.value.split(":").map(Number);
          transport.send(encodeDateChanged(id, 0, ((h ?? 0) * 3600 + (m ?? 0) * 60) * 1000));
        } else if (date.type === "datetime-local") {
          const [ymd, t] = date.value.split("T");
          const [y, mo, d] = (ymd ?? "").split("-").map(Number);
          const [h, mi] = (t ?? "").split(":").map(Number);
          const days = Math.round(Date.UTC(y ?? 0, (mo ?? 1) - 1, d ?? 1) / 86400000);
          transport.send(encodeDateChanged(id, days, ((h ?? 0) * 3600 + (mi ?? 0) * 60) * 1000));
        } else {
          const [y, m, d] = date.value.split("-").map(Number);
          const days = Math.round(Date.UTC(y ?? 0, (m ?? 1) - 1, d ?? 1) / 86400000);
          transport.send(encodeDateChanged(id, days, 0));
        }
      }
    }
  });

  // Sliders report live while dragging; text fields/editors report live while typing.
  document.addEventListener("input", (event) => {
    if (!transport.open) {
      return;
    }
    const target = event.target as Element | null;
    if (!target) {
      return;
    }
    const slider = target.closest<HTMLInputElement>("input[type=range]");
    if (slider) {
      const label = slider.closest<HTMLElement>("label.pathland-slider[data-pathland-id]");
      if (label) {
        transport.send(encodeValueChanged(Number(label.getAttribute("data-pathland-id")), Number(slider.value)));
      }
      return;
    }
    const textarea = target.closest<HTMLTextAreaElement>("textarea[data-pathland-id]");
    if (textarea) {
      transport.send(encodeTextChanged(Number(textarea.getAttribute("data-pathland-id")), textarea.value));
      return;
    }
    const input = target.closest<HTMLInputElement>("input[type=text],input[type=password]");
    if (!input) {
      return;
    }
    const label = input.closest<HTMLElement>("label.pathland-textfield[data-pathland-id]");
    if (label) {
      transport.send(encodeTextChanged(Number(label.getAttribute("data-pathland-id")), input.value));
    }
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot);
} else {
  boot();
}

import { describe, expect, it } from "vitest";
import { applyEnabled, applyProperty, alignmentCss, sizeCss } from "../src/classes";
import {
  PROP_ACTION_ID,
  PROP_ALIGNMENT,
  PROP_BACKGROUND_COLOR,
  PROP_BLUR_RADIUS,
  PROP_BORDER_COLOR,
  PROP_BORDER_EDGES,
  PROP_BORDER_RADIUS,
  PROP_BORDER_WIDTH,
  PROP_COLOR,
  PROP_DATE_PICKER_MODE,
  PROP_EVENT_LISTENERS,
  PROP_FONT_SIZE,
  PROP_FONT_WEIGHT,
  PROP_IS_SECURE,
  PROP_LINE_LIMIT,
  PROP_OPACITY,
  PROP_PROGRESS,
  PROP_ROLE,
  PROP_ROTATION_DEGREES,
  PROP_SHADOW_COLOR,
  PROP_SHADOW_RADIUS,
  PROP_SPACING,
  PROP_STATE,
  PROP_TEXT_ALIGNMENT,
  PROP_TEXT_CASE,
  PROP_TOGGLE_STYLE,
  PROP_VISIBLE,
  PROP_Z_INDEX,
  STATE_DISABLED,
  STATE_SELECTED,
  TOGGLE_STYLE_CHECKBOX,
  TOGGLE_STYLE_SWITCH,
  VAL_COLOR,
  VAL_F32,
  VAL_U32,
  VAL_U8,
  VAL_STRING,
} from "../src/constants";
import { bitsFromF32 } from "../src/format";

describe("Option A style appliers", () => {
  it("spacing -> gap", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_SPACING, VAL_F32, bitsFromF32(13));
    expect(el.style.gap).toBe("13px");
  });

  it("alignment (F32 enum) -> align-items", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_ALIGNMENT, VAL_F32, bitsFromF32(1)); // Center
    expect(el.style.alignItems).toBe("center");
  });

  it("opacity -> inline opacity", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_OPACITY, VAL_F32, bitsFromF32(0.5));
    expect(el.style.opacity).toBe("0.5");
  });

  it("font-size / font-weight -> inline typography", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_FONT_SIZE, VAL_F32, bitsFromF32(18));
    applyProperty(el, PROP_FONT_WEIGHT, VAL_F32, bitsFromF32(700));
    expect(el.style.fontSize).toBe("18px");
    expect(el.style.fontWeight).toBe("700");
  });

  it("text-align -> textAlign", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_TEXT_ALIGNMENT, VAL_F32, bitsFromF32(2)); // Trailing
    expect(el.style.textAlign).toBe("right");
  });

  it("text-case -> textTransform", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_TEXT_CASE, VAL_F32, bitsFromF32(1)); // Uppercase
    expect(el.style.textTransform).toBe("uppercase");
  });

  it("line-limit -> webkitLineClamp", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_LINE_LIMIT, VAL_U32, 2);
    expect(el.style.webkitLineClamp).toBe("2");
  });

  it("color -> rgba", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_COLOR, VAL_COLOR, 0xff000000);
    expect(el.style.color).toBe("rgba(0,0,0,1.000)");
  });

  it("background color -> rgba", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_BACKGROUND_COLOR, VAL_COLOR, 0x80ff0000);
    expect(el.style.backgroundColor).toBe("rgba(255,0,0,0.502)");
  });

  it("visible=0 -> display none, visible=1 -> restored", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_VISIBLE, VAL_U8, 0);
    expect(el.style.display).toBe("none");
    applyProperty(el, PROP_VISIBLE, VAL_U8, 1);
    expect(el.style.display).toBe("");
  });

  it("width FILL -> 100%, HUG -> fit-content, fixed -> px", () => {
    expect(sizeCss(-1)).toBe("100%");
    expect(sizeCss(-2)).toBe("fit-content");
    expect(sizeCss(320)).toBe("320px");
  });

  it("z-index -> zIndex", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_Z_INDEX, VAL_U32, 5);
    expect(el.style.zIndex).toBe("5");
  });

  it("border width + color + edges -> per-side borders", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_BORDER_WIDTH, VAL_F32, bitsFromF32(2));
    applyProperty(el, PROP_BORDER_COLOR, VAL_COLOR, 0xffff0000);
    applyProperty(el, PROP_BORDER_EDGES, VAL_U32, 0x03); // top + left
    expect(el.style.borderTop).toBe("2px solid rgba(255,0,0,1.000)");
    expect(el.style.borderLeft).toBe("2px solid rgba(255,0,0,1.000)");
    expect(el.style.borderRight).toBe("none");
    expect(el.style.borderBottom).toBe("none");
  });

  it("border-radius -> borderRadius", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_BORDER_RADIUS, VAL_F32, bitsFromF32(8));
    expect(el.style.borderRadius).toBe("8px");
  });

  it("shadow accumulates into boxShadow", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_SHADOW_RADIUS, VAL_F32, bitsFromF32(4));
    applyProperty(el, PROP_SHADOW_COLOR, VAL_COLOR, 0x80000000);
    expect(el.style.boxShadow).toContain("rgba(0,0,0,0.502)");
  });

  it("blur -> filter", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_BLUR_RADIUS, VAL_F32, bitsFromF32(3));
    expect(el.style.filter).toBe("blur(3px)");
  });

  it("rotation + scale -> transform", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_ROTATION_DEGREES, VAL_F32, bitsFromF32(90));
    applyProperty(el, 0x102e, VAL_F32, bitsFromF32(1.5)); // SCALE
    expect(el.style.transform).toBe("rotate(90deg) scale(1.5)");
  });
});

describe("semantic + control variants", () => {
  it("role -> role attribute", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_ROLE, VAL_F32, bitsFromF32(1)); // Button
    expect(el.getAttribute("role")).toBe("button");
  });

  it("state -> aria attributes", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_STATE, VAL_F32, bitsFromF32(STATE_DISABLED));
    expect(el.getAttribute("aria-disabled")).toBe("true");
    applyProperty(el, PROP_STATE, VAL_F32, bitsFromF32(STATE_SELECTED));
    expect(el.getAttribute("aria-selected")).toBe("true");
  });

  it("event-listeners -> data mask", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_EVENT_LISTENERS, VAL_U32, 0x0c); // POINTER_UP + KEY_DOWN
    expect(el.getAttribute("data-event-listeners")).toBe("12");
  });

  it("action-id -> data-action-id", () => {
    const el = document.createElement("div");
    applyProperty(el, PROP_ACTION_ID, VAL_U32, 77);
    expect(el.dataset.actionId).toBe("77");
  });

  it("is-secure flips input text -> password", () => {
    const tf = document.createElement("label");
    tf.className = "pathland-textfield";
    const input = document.createElement("input");
    input.type = "text";
    tf.appendChild(input);
    applyProperty(tf, PROP_IS_SECURE, VAL_U8, 1);
    expect(input.type).toBe("password");
    applyProperty(tf, PROP_IS_SECURE, VAL_U8, 0);
    expect(input.type).toBe("text");
  });

  it("toggle-style switch/checkbox set the input role", () => {
    const toggle = document.createElement("label");
    toggle.className = "pathland-toggle";
    const box = document.createElement("input");
    box.type = "checkbox";
    toggle.appendChild(box);
    applyProperty(toggle, PROP_TOGGLE_STYLE, VAL_F32, bitsFromF32(TOGGLE_STYLE_SWITCH));
    expect(box.getAttribute("role")).toBe("switch");
    applyProperty(toggle, PROP_TOGGLE_STYLE, VAL_F32, bitsFromF32(TOGGLE_STYLE_CHECKBOX));
    expect(box.hasAttribute("role")).toBe(false);
  });

  it("date-picker-mode time -> input[type=time]", () => {
    const input = document.createElement("input");
    input.type = "date";
    applyProperty(input, PROP_DATE_PICKER_MODE, VAL_F32, bitsFromF32(1));
    expect(input.type).toBe("time");
  });

  it("progress -> progress value", () => {
    const progress = document.createElement("progress");
    applyProperty(progress, PROP_PROGRESS, VAL_F32, bitsFromF32(0.4));
    expect(progress.value).toBe(0.4);
  });

  it("alignmentCss maps enum codes", () => {
    expect(alignmentCss(0)).toBe("flex-start");
    expect(alignmentCss(1)).toBe("center");
    expect(alignmentCss(2)).toBe("flex-end");
  });

  it("disabled toggles native controls + aria-disabled on other elements", () => {
    const button = document.createElement("button");
    applyEnabled(button, 0);
    expect(button.disabled).toBe(true);
    const div = document.createElement("div");
    applyEnabled(div, 0);
    expect(div.getAttribute("aria-disabled")).toBe("true");
    applyEnabled(div, 1);
    expect(div.hasAttribute("aria-disabled")).toBe(false);
  });
});

// Keep VAL_STRING referenced so the import documents the string path is handled in apply.ts.
void VAL_STRING;

import { describe, expect, it } from "vitest";
import {
  encodeDateChanged,
  encodeEditingChanged,
  encodeFocusChanged,
  encodeKeyDown,
  encodeKeyUp,
  encodePointerDown,
  encodePointerMove,
  encodePointerUp,
  encodeScroll,
  encodeSubmit,
  encodeTextChanged,
  encodeValueBits,
  encodeValueChanged,
  encodeWheel,
} from "../src/events";
import {
  CAT_EVENT,
  CMD_DATE_CHANGED,
  CMD_EDITING_CHANGED,
  CMD_FOCUS_CHANGED,
  CMD_KEY_DOWN,
  CMD_KEY_UP,
  CMD_POINTER_DOWN,
  CMD_POINTER_MOVE,
  CMD_POINTER_UP,
  CMD_SCROLL,
  CMD_SUBMIT,
  CMD_TEXT_CHANGED,
  CMD_VALUE_CHANGED,
  CMD_WHEEL,
  HEADER_SIZE,
  MAGIC,
  VERSION,
} from "../src/constants";
import { parseBatch, readString } from "../src/plpl";

function eventOf(bytes: Uint8Array): { category: number; command: number; flags: number; a: number; b: number; c: number } {
  return parseBatch(bytes).opcodes[0]!;
}

describe("event encoders", () => {
  it("encodePointerUp: header + single EVENT opcode, guest->host, x/y in B/C", () => {
    const bytes = encodePointerUp(42, 12.5, 33.25);
    expect(bytes.length).toBe(HEADER_SIZE + 16 + 4);
    const view = new DataView(bytes.buffer);
    expect(view.getUint32(0, true)).toBe(MAGIC);
    expect(view.getUint16(4, true)).toBe(VERSION);
    expect(view.getUint16(6, true)).toBe(0); // guest -> host
    expect(view.getUint32(12, true)).toBe(1); // opcodeCount
    const op = eventOf(bytes);
    expect(op.category).toBe(CAT_EVENT);
